Class Tarjeta
  Private Define saldo As Integer;

  Method Constructor(inicial As Integer)
    This.saldo <- 0;
    If inicial > 0 Then
      This.saldo <- inicial;
    EndIf
  EndMethod

  Method Cobrar(monto As Integer) As Boolean
    If monto <= 0 Or monto > This.saldo Then
      Return False;
    EndIf
    This.saldo <- This.saldo - monto;
    Return True;
  EndMethod

  Method Cargar(monto As Integer) As Boolean
    If monto <= 0 Then
      Return False;
    EndIf
    This.saldo <- This.saldo + monto;
    Return True;
  EndMethod

  Method Saldo() As Integer
    Return This.saldo;
  EndMethod
EndClass

Algorithm Comedor
  Define tarjeta As Tarjeta <- New Tarjeta(30);
  Write tarjeta.Cobrar(50), " ", tarjeta.Saldo();
  Write tarjeta.Cargar(-100), " ", tarjeta.Saldo();
  Write tarjeta.Cobrar(30), " ", tarjeta.Saldo();
EndAlgorithm
